</script><template><Head :title="t('Before you continue')"/><main class="disclosure"><div class="section-heading"><span class="brand">vocamilo</span><LanguageSwitch/></div><section class="panel"><h1>{{t('Before you continue')}}</h1><p>{{t('Administrators can view account names, email addresses and account status, and inspect collection titles, descriptions, words and definitions.')}}</p><p>{{t('Administrators can suspend or reactivate accounts, update collection details and disable sharing. Your personal notes are not included in these administrator views.')}}</p><p>{{t('Joining another person’s collection requires a separate choice about sharing your learning progress with its owner.')}}</p><p>{{t('You can return to Privacy choices to withdraw permission. Administrator access to your data will then stop.')}}</p><p>{{t('If you decline, you will be signed out. Your account and saved data will not be deleted.')}}</p><p>{{t('Administrator collection access is logged.')}}</p><p>{{t('These restrictions apply within the app. People with direct server or database access may still access stored data.')}}</p><p>{{t('Withdrawing stops future administrator visibility in the app. It cannot retract information already viewed or erase access logs.')}}</p><form @submit.prevent="form.post('/account/disclosure')"><Errors :errors="form.errors"/><label class="consent-check"><input type="checkbox" v-model="form.accepted" required/>{{t('I understand and agree to this administrator access.')}}</label><div class="form-actions"><button type="button" class="button secondary" :disabled="form.processing" @click="form.delete('/account/disclosure')">{{t('Decline and sign out')}}</button><button class="button" :disabled="!form.accepted||form.processing">{{t('Agree and continue')}}</button></div></form></section></main></template><style scoped>.disclosure{max-width:760px;margin:4vh auto;padding:20px}.disclosure p{line-height:1.65}.consent-check{display:flex;align-items:flex-start;gap:12px;margin-